package org.jfree.data.statistics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.data.KeyedObjects2D;
import org.jfree.data.Range;
import org.jfree.data.RangeInfo;
import org.jfree.data.general.AbstractDataset;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class DefaultBoxAndWhiskerCategoryDataset_add_TriageGen1Test {

    private DefaultBoxAndWhiskerCategoryDataset dataset;

    @Before
    public void setUp() {
        dataset = new DefaultBoxAndWhiskerCategoryDataset();
    }

    /**
     * Helper to create a BoxAndWhiskerItem.
     * Note: Since BoxAndWhiskerItem is likely a complex object, 
     * we assume a standard constructor or mock-like behavior.
     */
    private BoxAndWhiskerItem createItem(Double minOutlier, Double maxOutlier) {
        // Assuming constructor: BoxAndWhiskerItem(List values, Double minOutlier, Double maxOutlier, ...)
        // Given the method access, we must provide valid numbers.
        return new BoxAndWhiskerItem(null, minOutlier, maxOutlier, null, null, null, null);
    }

    @Test
    public void testAddFirstItemSetsBounds() {
        BoxAndWhiskerItem item = createItem(10.0, 50.0);
        dataset.add(item, "Row1", "Col1");

        assertEquals(10.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(50.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddItemUpdatesNewMaxAndMin() {
        // First item: 10 to 50
        dataset.add(createItem(10.0, 50.0), "R1", "C1");

        // Second item: 5 to 100 (expands bounds)
        dataset.add(createItem(5.0, 100.0), "R2", "C2");

        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(100.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddItemDoesNotExpandBounds() {
        // First item: 10 to 50
        dataset.add(createItem(10.0, 50.0), "R1", "C1");

        // Second item: 20 to 40 (within current bounds)
        dataset.add(createItem(20.0, 40.0), "R2", "C2");

        assertEquals(10.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(50.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddSameLocationTriggersUpdateBounds() {
        // First item
        dataset.add(createItem(10.0, 50.0), "R1", "C1");

        // Second item at same Row/Col index should trigger 'updateBounds()' branch
        // Even if values are different, the logic enters the 'if' branch for same r/c
        dataset.add(createItem(5.0, 100.0), "R1", "C1");

        // Since updateBounds() is called, it re-calculates from all items in data
        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(100.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddWithNullMinOutlier() {
        // Tests the branch: if (item.getMinOutlier() != null)
        BoxAndWhiskerItem item = createItem(null, 100.0);
        dataset.add(item, "R1", "C1");

        // minval becomes Double.NaN, so minimumRangeValue becomes NaN if first item
        // However, the code sets it via: if (Double.isNaN(this.minimumRangeValue))
        // If minval is NaN, it might stay NaN or behave based on comparison.
        // In the provided code, if minval is NaN, minimumRangeValue becomes NaN.
        assertEquals(Double.NaN, dataset.getRangeLowerBound(true), 0.0);
        assertEquals(100.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddMultipleItemsDifferentLocations() {
        dataset.add(createItem(20.0, 30.0), "R1", "C1");
        dataset.add(createItem(10.0, 40.0), "R2", "C2");
        dataset.add(createItem(5.0, 50.0), "R3", "C3");

        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(50.0, dataset.getRangeUpperBound(true), 0.001);
    }
}
